export interface ConnectorConfig {
  /** GitHub repository owner (username or organization) */
  githubOwner: string
  /** GitHub repository name */
  githubRepo: string
  /** GitHub personal access token (from GITHUB_TOKEN env var) */
  githubToken: string
  /** Zendesk subdomain (e.g., 'mycompany' for mycompany.zendesk.com) */
  zendeskSubdomain: string
  /** Zendesk API token (from ZENDESK_TOKEN env var, format: email/token) */
  zendeskToken: string
  /** Optional injected fetch for testing */
  fetch?: typeof fetch
}

export interface ZendeskTicketCreatedPayload {
  account_id: number
  detail: {
    actor_id: string
    assignee_id: string
    brand_id: string
    created_at: string
    custom_status: string
    description: string
    external_id: string | null
    form_id: string
    group_id: string
    id: string
    is_public: boolean
    organization_id: string
    priority: string
    requester_id: string
    status: string
    subject: string
    submitter_id: string
    tags: string[]
    type: string | null
    updated_at: string
    via: {
      channel: string
    }
  }
  event: {
    meta: {
      sequence: {
        id: string
        position: number
      }
    }
  }
  id: string
  subject: string
  time: string
  type: string
  zendesk_event_version: string
}

export interface HandleResult {
  githubIssueNumber: number
  githubIssueUrl: string
  zendeskCommentId: number
}

async function handle(
  payload: ZendeskTicketCreatedPayload,
  config: ConnectorConfig
): Promise<HandleResult> {
  const fetchImpl = config.fetch ?? fetch

  // Validate required fields
  if (!payload.detail?.subject) {
    throw new Error('Missing required field: detail.subject')
  }
  if (!payload.detail?.description) {
    throw new Error('Missing required field: detail.description')
  }
  if (!payload.detail?.id) {
    throw new Error('Missing required field: detail.id')
  }

  const { subject, description, id: ticketId } = payload.detail

  // Step 1: Create GitHub issue
  const githubUrl = `https://api.github.com/repos/${config.githubOwner}/${config.githubRepo}/issues`
  const githubBody = {
    title: subject,
    body: description,
    labels: [ticketId],
  }

  const githubResponse = await fetchImpl(githubUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.githubToken}`,
      Accept: 'application/vnd.github+json',
      'Content-Type': 'application/json',
      'User-Agent': 'patchbay-connector',
    },
    body: JSON.stringify(githubBody),
  })

  if (!githubResponse.ok) {
    throw new Error(
      `GitHub create issue failed: ${githubResponse.status} ${githubResponse.statusText} at ${githubUrl}`
    )
  }

  const githubIssue = (await githubResponse.json()) as {
    id: number
    number: number
    html_url: string
    url: string
  }

  // Step 2: Post comment to Zendesk ticket with GitHub issue URL
  const zendeskUrl = `https://${config.zendeskSubdomain}.zendesk.com/api/v2/tickets/${ticketId}/comments.json`
  const commentBody = {
    comment: {
      body: `GitHub issue created: ${githubIssue.html_url}`,
      public: true,
    },
  }

  const zendeskResponse = await fetchImpl(zendeskUrl, {
    method: 'POST',
    headers: {
      Authorization: `Bearer ${config.zendeskToken}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(commentBody),
  })

  if (!zendeskResponse.ok) {
    throw new Error(
      `Zendesk add comment failed: ${zendeskResponse.status} ${zendeskResponse.statusText} at ${zendeskUrl}`
    )
  }

  const zendeskComment = (await zendeskResponse.json()) as {
    comment: {
      id: number
      body: string
      public: boolean
      author_id: number
      created_at: string
    }
  }

  return {
    githubIssueNumber: githubIssue.number,
    githubIssueUrl: githubIssue.html_url,
    zendeskCommentId: zendeskComment.comment.id,
  }
}

export { handle }

import { describe, it, expect, vi, beforeEach } from 'vitest'
import { handle, ConnectorConfig, ZendeskTicketCreatedPayload } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall,
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      githubOwner: 'octocat',
      githubRepo: 'Hello-World',
      githubToken: 'gh_test_token',
      zendeskSubdomain: 'mycompany',
      zendeskToken: 'email/token',
      fetch,
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.githubIssueNumber).toBe(1347)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/Hello-World/issues/1347')
    expect(result.zendeskCommentId).toBe(12345)
  })
})

describe('handle', () => {
  let baseConfig: ConnectorConfig
  let calls: RecordedCall[]

  beforeEach(() => {
    baseConfig = {
      githubOwner: 'octocat',
      githubRepo: 'Hello-World',
      githubToken: 'gh_test_token',
      zendeskSubdomain: 'mycompany',
      zendeskToken: 'email/token',
    }
    calls = []
  })

  function makeFetch(handler: (req: RecordedCall) => Response | Promise<Response>) {
    const { fetch, calls: recordedCalls } = fakeFetch(handler)
    calls.push(...recordedCalls)
    return fetch
  }

  it('creates GitHub issue and posts Zendesk comment on happy path', async () => {
    const fetch = makeFetch((req) => {
      if (req.url.includes('/repos/octocat/Hello-World/issues')) {
        return jsonResponse(
          {
            id: 1347,
            number: 1347,
            html_url: 'https://github.com/octocat/Hello-World/issues/1347',
            url: 'https://api.github.com/repos/octocat/Hello-World/issues/1347',
          },
          201
        )
      }
      if (req.url.includes('/tickets/14038/comments.json')) {
        return jsonResponse(
          {
            comment: {
              id: 12345,
              body: 'GitHub issue created: https://github.com/octocat/Hello-World/issues/1347',
              public: true,
              author_id: 987654321,
              created_at: '2025-01-14T20:30:00Z',
            },
          },
          201
        )
      }
      return jsonResponse({ error: 'not found' }, 404)
    })

    const payload = SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload
    const result = await handle(payload, { ...baseConfig, fetch })

    expect(result.githubIssueNumber).toBe(1347)
    expect(result.githubIssueUrl).toBe('https://github.com/octocat/Hello-World/issues/1347')
    expect(result.zendeskCommentId).toBe(12345)

    expect(calls).toHaveLength(2)

    // GitHub create issue call
    const githubCall = calls[0]
    expect(githubCall.method).toBe('POST')
    expect(githubCall.url).toBe('https://api.github.com/repos/octocat/Hello-World/issues')
    expect(githubCall.headers.get('authorization')).toBe('Bearer gh_test_token')
    expect(githubCall.json).toEqual({
      title: 'Alpha top - group over queue',
      body: 'OCR Queues Regression Tests',
      labels: ['14038'],
    })

    // Zendesk add comment call
    const zendeskCall = calls[1]
    expect(zendeskCall.method).toBe('POST')
    expect(zendeskCall.url).toBe('https://mycompany.zendesk.com/api/v2/tickets/14038/comments.json')
    expect(zendeskCall.headers.get('authorization')).toBe('Bearer email/token')
    expect(zendeskCall.json).toEqual({
      comment: {
        body: 'GitHub issue created: https://github.com/octocat/Hello-World/issues/1347',
        public: true,
      },
    })
  })

  it('uses Bearer auth for both GitHub and Zendesk', async () => {
    const fetch = makeFetch((req) => {
      if (req.url.includes('/repos/')) {
        return jsonResponse(
          { id: 1, number: 1, html_url: 'https://github.com/octocat/Hello-World/issues/1', url: '' },
          201
        )
      }
      return jsonResponse({ comment: { id: 1, body: '', public: true, author_id: 1, created_at: '' } }, 201)
    })

    await handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, {
      ...baseConfig,
      githubToken: 'gh_token_123',
      zendeskToken: 'zd_token_456',
      fetch,
    })

    expect(calls[0].headers.get('authorization')).toBe('Bearer gh_token_123')
    expect(calls[1].headers.get('authorization')).toBe('Bearer zd_token_456')
  })

  it('maps subject to title, description to body, ticket.id to labels', async () => {
    const fetch = makeFetch((req) => {
      if (req.url.includes('/repos/')) {
        return jsonResponse(
          { id: 1, number: 1, html_url: 'https://github.com/octocat/Hello-World/issues/1', url: '' },
          201
        )
      }
      return jsonResponse({ comment: { id: 1, body: '', public: true, author_id: 1, created_at: '' } }, 201)
    })

    const customPayload: ZendeskTicketCreatedPayload = {
      ...SOURCE_EXAMPLE,
      detail: {
        ...SOURCE_EXAMPLE.detail,
        subject: 'Custom Subject',
        description: 'Custom Description',
        id: '99999',
      },
    }

    await handle(customPayload, { ...baseConfig, fetch })

    expect(calls[0].json).toEqual({
      title: 'Custom Subject',
      body: 'Custom Description',
      labels: ['99999'],
    })
  })

  it('throws descriptive error when detail.subject is missing', async () => {
    const fetch = makeFetch(() => jsonResponse({}, 200))
    const payload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, subject: undefined as unknown as string },
    }

    await expect(handle(payload as unknown as ZendeskTicketCreatedPayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: detail.subject'
    )
  })

  it('throws descriptive error when detail.description is missing', async () => {
    const fetch = makeFetch(() => jsonResponse({}, 200))
    const payload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, description: undefined as unknown as string },
    }

    await expect(handle(payload as unknown as ZendeskTicketCreatedPayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: detail.description'
    )
  })

  it('throws descriptive error when detail.id is missing', async () => {
    const fetch = makeFetch(() => jsonResponse({}, 200))
    const payload = {
      ...SOURCE_EXAMPLE,
      detail: { ...SOURCE_EXAMPLE.detail, id: undefined as unknown as string },
    }

    await expect(handle(payload as unknown as ZendeskTicketCreatedPayload, { ...baseConfig, fetch })).rejects.toThrow(
      'Missing required field: detail.id'
    )
  })

  it('throws with status and endpoint when GitHub returns non-2xx', async () => {
    const fetch = makeFetch(() => jsonResponse({ message: 'Bad credentials' }, 401))

    await expect(
      handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, { ...baseConfig, fetch })
    ).rejects.toThrow('GitHub create issue failed: 401 Unauthorized at https://api.github.com/repos/octocat/Hello-World/issues')
  })

  it('throws with status and endpoint when Zendesk returns non-2xx', async () => {
    const fetch = makeFetch((req) => {
      if (req.url.includes('/repos/')) {
        return jsonResponse(
          { id: 1, number: 1, html_url: 'https://github.com/octocat/Hello-World/issues/1', url: '' },
          201
        )
      }
      return jsonResponse({ error: 'Forbidden' }, 403)
    })

    await expect(
      handle(SOURCE_EXAMPLE as unknown as ZendeskTicketCreatedPayload, { ...baseConfig, fetch })
    ).rejects.toThrow(
      'Zendesk add comment failed: 403 Forbidden at https://mycompany.zendesk.com/api/v2/tickets/14038/comments.json'
    )
  })
})

